# Try with the stripped binary + separate debug for SGen worker, or use nm/readelf to check
cd /tmp/sv-97e5d91a2b3b46e3b6ecafddc7918fc8
# Check dynamic symbols in stripped binary for those addresses
aarch64-linux-gnu-nm -D libmonosgen-2.0.so 2>/dev/null | sort | awk -v addr1="2f4b20" -v addr2="2f4c84" '
{
  if ($1 <= addr1) last1 = $0
  if ($1 <= addr2) last2 = $0
}
END {
  print "Nearest to 0x2f4b20: " last1
  print "Nearest to 0x2f4c84: " last2
}'

