arguments.command:
# Try all symbol types, sorted by address, find what functions contain these
cd /tmp/sv-97e5d91a2b3b46e3b6ecafddc7918fc8
aarch64-linux-gnu-nm -n libmonosgen-2.0.so.dbg 2>/dev/null | awk '
{
  addr = strtonum("0x" $1)
  if (addr <= 0x2f4b20) { name1 = $3; addr1 = $1 }
  if (addr <= 0x2f4c84) { name2 = $3; addr2 = $1 }
}
END {
  print "0x2f4b20 in: " name1 " (starts at 0x" addr1 ")"
  print "0x2f4c84 in: " name2 " (starts at 0x" addr2 ")"
}'

